mapper.select:
SELECT n.*, u.real_name AS publisher_name, m.name AS meeting_name FROM t_notice n LEFT JOIN ssms_auth.t_user u ON n.published_by = u.id LEFT JOIN t_meeting m ON n.meeting_id = m.id WHERE n.deleted = 0
AND n.meeting_id = #{meetingId}
AND n.type = #{type}
AND (n.title LIKE CONCAT('%', #{keyword}, '%') OR n.content LIKE CONCAT('%', #{keyword}, '%'))
AND (n.target_role IS NULL OR n.target_role = #{targetRole})
ORDER BY n.is_top DESC, n.create_time DESC
